import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Hako","description":"Hako 是面向 Apple NetworkExtension 的开源 mihomo 分叉内核，为 Clash 提供多协议、规则分流、DNS 与本机控制能力。","frontmatter":{"title":"Hako","description":"Hako 是面向 Apple NetworkExtension 的开源 mihomo 分叉内核，为 Clash 提供多协议、规则分流、DNS 与本机控制能力。","keywords":["Hako内核","mihomo iOS内核","NetworkExtension代理内核","开源网络内核","Hako xcframework"],"jsonLd":{"@context":"https://schema.org","@type":"SoftwareSourceCode","name":"Hako","description":"面向 Apple NetworkExtension 的开源 mihomo 分叉内核，为 Clash 提供多协议与规则分流能力。","codeRepository":"https://github.com/TokenPLS/Hako","license":"https://www.gnu.org/licenses/gpl-3.0.html","programmingLanguage":"Go","runtimePlatform":["iOS","iPadOS","macOS","tvOS"],"isBasedOn":"https://github.com/MetaCubeX/mihomo","inLanguage":"zh-CN"}},"headers":[],"relativePath":"zh/hako.md","filePath":"zh/hako.md","lastUpdated":1785318168000}`),a={name:`zh/hako.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="hako" tabindex="-1">Hako <a class="header-anchor" href="#hako" aria-label="Permalink to “Hako”">​</a></h1><p><strong>高性能 · 自适应 · 开源内核</strong></p><p>Hako 是驱动 Clash 的开源网络内核。它将 <a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">mihomo</a> 的稳定版本分叉封装为 <code>Hako.xcframework</code>，通过 Swift 与 Objective-C 接口提供给 Apple App。</p><h2 id="为-apple-平台而生" tabindex="-1">为 Apple 平台而生 <a class="header-anchor" href="#为-apple-平台而生" aria-label="Permalink to “为 Apple 平台而生”">​</a></h2><p>Clash 在 Apple 的 NetworkExtension 环境中运行 Hako，数据包全程通过公开的 <code>NEPacketTunnelFlow</code> API 收发，完整遵循 Apple 的公开系统接口。</p><p>Hako 针对 Packet Tunnel 的内存与能效目标进行了专门调校。内核会在本机提供吞吐、连接数、内存与健康状态，让 App 能够如实展示运行情况。</p><h2 id="真机测试数据" tabindex="-1">真机测试数据 <a class="header-anchor" href="#真机测试数据" aria-label="Permalink to “真机测试数据”">​</a></h2><p>Hako 公开的发布证据包含 iPad Pro（M2）上的受控测试：</p><table tabindex="0"><thead><tr><th>测试</th><th>结果</th></tr></thead><tbody><tr><td>公网 Speedtest</td><td>下行 924 Mbps · 上行 545 Mbps · 延迟 5 ms</td></tr><tr><td>测速时内核内存</td><td>18.7 MiB</td></tr><tr><td>30 分钟压力测试</td><td>搬运 16.49 GB · 0 掉线 · 0 丢包 · 0 崩溃</td></tr><tr><td>400 条并发连接</td><td>在 50 MiB 测试预算下使用 39.6 MiB</td></tr></tbody></table><p>这些数据记录了指定硬件、网络与构建下的实测结果，实际表现会随设备、线路与配置而变化。</p><h2 id="内核能力" tabindex="-1">内核能力 <a class="header-anchor" href="#内核能力" aria-label="Permalink to “内核能力”">​</a></h2><ul><li><strong>协议：</strong> Shadowsocks、VMess、VLESS、Trojan、Snell、Hysteria、 Hysteria2、TUIC、WireGuard、AnyTLS、SSH 等。</li><li><strong>DNS：</strong> DoH、DoT、DoQ、fake-IP、流量嗅探与分域名解析规则。</li><li><strong>路由：</strong> domain、IP-CIDR、GEOIP、GEOSITE、RULE-SET 与逻辑规则。</li><li><strong>策略组：</strong> select、url-test、fallback、load-balance，包含健康检查与远程 Provider。</li><li><strong>本机控制：</strong> 状态、流量、连接、代理、日志、延迟测试与连接控制均走 App 私有的本机通道。</li></ul><h2 id="开源与审计" tabindex="-1">开源与审计 <a class="header-anchor" href="#开源与审计" aria-label="Permalink to “开源与审计”">​</a></h2><p>Hako 跟随钉定的 mihomo 稳定版本。Hako 相对上游的源代码改动以 GPL-3.0 公开，任何人都可以独立审阅；每一处实现与安全疑问都可以直接对照代码核验。</p><p>Hako 由 Clash &amp; Hako Team 作为独立分叉维护，MetaCubeX 与 SagerNet 名称仅用于说明技术来源。首个正式 <code>v*-hako.*</code> Release 发布前，SDK 使用 pre-1.0 版本标识。</p><h2 id="源代码" tabindex="-1">源代码 <a class="header-anchor" href="#源代码" aria-label="Permalink to “源代码”">​</a></h2><ul><li><a href="https://github.com/TokenPLS/Hako" target="_blank" rel="noreferrer">Hako 内核</a></li><li><a href="https://github.com/TokenPLS/Hako/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">完整中文 README</a></li><li><a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">mihomo 上游项目</a></li><li><a href="https://github.com/TokenPLS/Hako/blob/main/SECURITY.md" target="_blank" rel="noreferrer">安全政策</a></li></ul>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};